import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Legacy and Modern Combat","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/legacy-and-modern.md","filePath":"en/guide/combat/legacy-and-modern.md"}'),o={name:"en/guide/combat/legacy-and-modern.md"};function n(d,a,l,s,c,h){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="legacy-and-modern-combat" tabindex="-1">Legacy and Modern Combat <a class="header-anchor" href="#legacy-and-modern-combat" aria-label="Permalink to &quot;Legacy and Modern Combat&quot;">​</a></h1><p><strong>Status:</strong> Proposed · New dual-mode actions not implemented.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Both modes start with target selection and share base weapon rules.</li><li><a href="/Syrolands-Public/en/guide/glossary.html#legacy-combat">Legacy</a> attacks automatically; <a href="/Syrolands-Public/en/guide/glossary.html#modern-combat">Modern</a> lets you choose when an available action starts.</li><li>Modern is the preferred experimental direction; Legacy remains an accessibility and familiarity alternative.</li></ul><p><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Meaning</th></tr></thead><tbody><tr><td>Basic attack</td><td>Legacy follows an automatic cadence; Modern waits for your input.</td></tr><tr><td>Offensive <a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Special Attack</a></td><td>Queue the next valid swing in Legacy; trigger an available action in Modern.</td></tr><tr><td>Manual defense</td><td>Available in both modes, subject to preparation, <a href="/Syrolands-Public/en/guide/combat/stamina-and-reactive-combat.html">stamina</a> and <a href="/Syrolands-Public/en/guide/combat/stamina-and-reactive-combat.html">recovery</a>.</td></tr><tr><td>Shared limits</td><td>Starting now does not mean hitting instantly or skipping recovery.</td></tr><tr><td>Archery</td><td>Ordinary shots require no timing minigame. Modern controls release; selected special shots may share a timing challenge.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands</th></tr></thead><tbody><tr><td>Automatic attack cadence</td><td>Legacy preserves the familiar approach; Modern adds deliberate initiation.</td></tr><tr><td>Special moves vary by era</td><td>Learned actions share costs and phases across both proposed modes.</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Queue Thrust for the next valid Legacy swing, or start it in Modern when the opening appears. The same action still consumes stamina and leaves recovery afterward.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Special Attacks</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/legacy-and-modern.html">Read the full design specification</a></p>',15)])])}const p=e(o,[["render",n]]);export{u as __pageData,p as default};
